use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Number(num) = input {
        if let Some(cents) = num.as_i64() {
            let pounds = cents / 100;
            let remainder = cents % 100;
            let mut result = format!("{}.{}", pounds, remainder.abs());
            if remainder < 0 {
                result.insert(0, '-');
            }
            result.push_str(".00");
            result.truncate(result.len() - 2);
            return Value::String(result);
        }
    }
    Value::Null
}
